use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_greater_spec(n: int, a: Seq<int>) -> bool {
    forall|i: int| 0 <= i < a.len() ==> n > a[i]
}

fn is_greater(n: i32, a: &Vec<i32>) -> (result: bool)
    requires
        a.len() > 0,  // Non-empty array as stated in the problem
    ensures
        result == is_greater_spec(n as int, a@)
{
    let mut i: usize = 0;
    let mut all_greater: bool = true;
    
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            all_greater == is_greater_spec(n as int, a@.subrange(0, i as int)),
        decreases a.len() - i,
    {
        if a[i] >= n {
            all_greater = false;
        }
        i = i + 1;
    }
    
    all_greater
}

}
